function buildChapters(book:string, rows:string[][], chapterCount:number, sectionMap:(n:number)=>string, sharedQuestions:string[], sharedConnections:string[]):DeepChapter[] {
  return rows.slice(0,chapterCount).map((r,i)=>{
    const n=i+1;
    const [title,summary]=r;
    const section=sectionMap(n);
    const beats = n===1 ? [summary, `This chapter establishes the opening movement of the ${book} narrative.`, `It should be read in relation to the book's larger ${section.toLowerCase()} structure.`] : [summary, `The chapter develops the ${section.toLowerCase()} movement through its principal characters, actions and theological claims.`, `Its meaning becomes clearer when read alongside the chapters immediately before and after it.`];
    const themes = section.includes("Creation") ? ["Origins","Humanity","Order"] : section.includes("Abraham") ? ["Covenant","Promise","Family"] : section.includes("Jacob") ? ["Family","Blessing","Land"] : section.includes("Joseph") ? ["Providence","Family","Egypt"] : section.includes("Deliverance") ? ["Liberation","Moses","Egypt"] : section.includes("Sinai") ? ["Covenant","Law","Holiness"] : section.includes("Tabernacle") ? ["Worship","Priesthood","Presence"] : section.includes("Wilderness") ? ["Wilderness","Community","Testing"] : section.includes("Covenant") ? ["Covenant","Obedience","Land"] : [book,"Covenant","Community"];
    return c(n,title,summary,beats,themes,`Historical study should distinguish the biblical narrative from independently established evidence. For ${book} ${n}, the most useful context comes from the ancient Near Eastern political, geographic, social and religious world relevant to the chapter and from comparison with the site's people, places, events and evidence records.`,sharedQuestions.slice(0,3),sharedConnections.slice(0,3));
  });
}

